import { useRef, useState } from 'react'
import { useNavigate } from 'react-router-dom'
import {
    getMerchantUserList,
    updateMerchantUserStatus,
    PlatformUserTypes
} from '@/apis/admin/platform-user'
import ExcelTable from '@/components/exportExcel'
import AddMerchantModal from './components/AddMerchantModal'
import {
    ActionType,
    ProFormInstance,
    ProColumns,
} from '@ant-design/pro-components'
import {
    Button,
    message,
    Tag,
    Tooltip,
    Popconfirm,
    Modal,
    Space,
} from 'antd'
import {
    PlusOutlined,
    StopOutlined,
    CheckCircleOutlined,
    EyeOutlined,
    DeleteOutlined
} from '@ant-design/icons'
import { ResultEnum } from '@/utils/enums/httpEnum'
import dayjs from 'dayjs'

// 商户状态映射
const merchantStatusMap: Record<number, { text: string; color: string }> = {
    1: { text: '启用', color: 'success' },
    2: { text: '禁用', color: 'error' },
}

// 商户身份映射
const identityTypeMap: Record<number, { text: string; color: string }> = {
    1: { text: '商户', color: 'blue' },
    2: { text: '运维人员', color: 'orange' },
}

// 格式化时间
const formatTime = (time: string) => {
    if (!time) {
return '-'
}
    return dayjs(time).format('YYYY-MM-DD HH:mm:ss')
}

const Merchant: React.FC = () => {
    const navigate = useNavigate()
    const actionRef = useRef<ActionType>()
    const formRef = useRef<ProFormInstance>()
    const [modalVisible, setModalVisible] = useState(false)

    // 导出商户列表
    const handleExport = () => {
        message.info('导出功能开发中')
    }

    // 打开新增弹窗
    const handleOpenAdd = () => {
        setModalVisible(true)
    }

    // 保存成功回调
    const handleSaveSuccess = () => {
        setModalVisible(false)
        actionRef.current?.reload()
    }

    // 禁用/启用商户
    const handleToggleStatus = async (record: PlatformUserTypes.MerchantUserListDto) => {
        try {
            const newStatus = record.status === 1 ? 2 : 1
            const res = await updateMerchantUserStatus(record.id, {
                userId: record.id,
                status: newStatus
            })

            if (res.code === ResultEnum.SUCCESS) {
                message.success(`${record.status === 1 ? '禁用' : '启用'}成功`)
                actionRef.current?.reload()
            } else {
                message.error(res.message || '操作失败')
            }
        } catch (e) {
            message.error('操作失败')
        }
    }

    // 删除商户
    const handleDelete = (record: PlatformUserTypes.MerchantUserListDto) => {
        Modal.confirm({
            title: '删除确认',
            content: (
                <div>
                    <p>确定要删除商户「{record.merchantName}」吗？</p>
                    <p style={{ color: '#999', fontSize: 12 }}>删除前需先解绑所有柜子</p>
                </div>
            ),
            onOk: () => {
                message.success('删除成功')
                actionRef.current?.reload()
            }
        })
    }

    // 查看详情
    const handleViewDetail = (record: PlatformUserTypes.MerchantUserListDto) => {
        navigate(`/user/merchant/detail/${record.id}`)
    }

    // 渲染身份标签
    const renderIdentityTags = (identityType: number) => {
        const types: number[] = []
        if (identityType & 1) {
            types.push(1)
        }
        if (identityType & 2) {
            types.push(2)
        }

        return (
            <Space size="small">
                {types.map(type => {
                    const identity = identityTypeMap[type]
                    return (
                        <Tag key={type} color={identity?.color || 'default'}>
                            {identity?.text || '未知'}
                        </Tag>
                    )
                })}
            </Space>
        )
    }

    // 表格列定义
    const columns: ProColumns<PlatformUserTypes.MerchantUserListDto>[] = [
        {
            title: '商户ID',
            dataIndex: 'id',
            key: 'id',
            width: 120,
            hideInSearch: true,
            render: (text) => (
                <span style={{ fontFamily: 'Courier New, monospace', fontWeight: 500 }}>
                    {text}
                </span>
            ),
        },
        {
            title: '商户名称',
            dataIndex: 'merchantName',
            key: 'merchantName',
            width: 200,
            ellipsis: true,
        },
        {
            title: '联系人姓名',
            dataIndex: 'contactUser',
            key: 'contactUser',
            width: 120,
        },
        {
            title: '联系人手机号',
            dataIndex: 'contactPhone',
            key: 'contactPhone',
            width: 140,
        },
        {
            title: '商户身份',
            dataIndex: 'identityType',
            key: 'identityType',
            width: 180,
            valueType: 'select',
            valueEnum: {
                1: { text: '商户' },
                2: { text: '运维人员' },
                3: { text: '双重身份' },
            },
            render: (_, record) => renderIdentityTags(record.identityType),
        },
        {
            title: '绑定设备数',
            dataIndex: 'bindDeviceNum',
            key: 'bindDeviceNum',
            width: 120,
            hideInSearch: true,
            render: (text) => (
                <span style={{ fontFamily: 'Courier New, monospace' }}>
                    {text || 0}
                </span>
            ),
        },
        {
            title: '状态',
            dataIndex: 'status',
            key: 'status',
            width: 100,
            valueType: 'select',
            valueEnum: {
                1: { text: '启用', status: 'Success' },
                2: { text: '禁用', status: 'Error' },
            },
            render: (_, record) => {
                const status = merchantStatusMap[record.status]
                return <Tag color={status?.color || 'default'}>{status?.text || '未知'}</Tag>
            },
        },
        {
            title: '创建时间',
            dataIndex: 'createdAt',
            key: 'createdAt',
            width: 170,
            hideInSearch: true,
            render: (text) => (
                <span style={{ fontSize: 13, whiteSpace: 'nowrap' }}>
                    {formatTime(text as string)}
                </span>
            ),
        },
        {
            title: '操作',
            key: 'option',
            valueType: 'option',
            fixed: 'right',
            width: 120,
            render: (_, record) => [
                <Tooltip title="查看详情" key={`${record.id}-view`}>
                    <Button
                        type="link"
                        title="查看详情"
                        icon={<EyeOutlined />}
                        onClick={() => handleViewDetail(record)}
                    />
                </Tooltip>,
                record.status === 1 ? (
                    <Tooltip title="禁用" key={`${record.id}-disable`}>
                        <Popconfirm
                            title={`确定要禁用商户「${record.merchantName}」吗？`}
                            onConfirm={() => handleToggleStatus(record)}
                        >
                            <Button
                                type="link"
                                danger
                                title="禁用"
                                icon={<StopOutlined />}
                            />
                        </Popconfirm>
                    </Tooltip>
                ) : (
                    <Tooltip title="启用" key={`${record.id}-enable`}>
                        <Button
                            type="link"
                            title="启用"
                            icon={<CheckCircleOutlined />}
                            style={{ color: '#52c41a' }}
                            onClick={() => handleToggleStatus(record)}
                        />
                    </Tooltip>
                ),
                <Tooltip title="删除" key={`${record.id}-delete`}>
                    <Button
                        type="link"
                        danger
                        title="删除"
                        icon={<DeleteOutlined />}
                        onClick={() => handleDelete(record)}
                    />
                </Tooltip>,
            ],
        },
    ]

    return (
        <>
            <ExcelTable
                key="merchant-list"
                formRef={formRef}
                columns={columns}
                requestFn={async (params) => {
                    const { page, pageSize, merchantName, contactUser, contactPhone, identityType, status, ...rest } = params
                    return await getMerchantUserList({
                        page,
                        pageSize,
                        merchantName,
                        contactUser,
                        contactPhone,
                        identityType,
                        status,
                        ...rest
                    })
                }}
                actionRef={actionRef}
                rowSelection={false}
                options={{
                    fullScreen: false,
                    reload: true,
                    setting: false,
                    density: false
                }}
                toolBarRenderFn={() => [
                    <Button
                        key="add"
                        type="primary"
                        icon={<PlusOutlined />}
                        onClick={handleOpenAdd}
                    >
                        新增商户
                    </Button>,
                ]}
                scroll={{ x: 1400 }}
            />

            {/* 新增商户弹窗 */}
            <AddMerchantModal
                open={modalVisible}
                onCancel={() => setModalVisible(false)}
                onSuccess={handleSaveSuccess}
            />
        </>
    )
}

export default Merchant