import { useState, useEffect } from 'react'
import {
  addMerchantUser,
  PlatformUserTypes,
} from '@/apis/admin/platform-user'
import { DeviceManagementTypes } from '@/apis/admin/device-management'
import DeviceSelector from '@/components/DeviceSelector'
import {
  Modal,
  Form,
  Input,
  Checkbox,
  Tag,
  Row,
  Col,
  message
} from 'antd'
import { ResultEnum } from '@/utils/enums/httpEnum'

interface AddMerchantModalProps {
  open: boolean
  onCancel: () => void
  onSuccess: () => void
}

const AddMerchantModal: React.FC<AddMerchantModalProps> = ({
  open,
  onCancel,
  onSuccess
}) => {
  const [form] = Form.useForm()
  const [confirmLoading, setConfirmLoading] = useState(false)
  const [selectedDevices, setSelectedDevices] = useState<DeviceManagementTypes.DeviceListDto[]>([])

  // 弹窗打开时重置表单
  useEffect(() => {
    if (open) {
      form.resetFields()
      setSelectedDevices([])
    }
  }, [open, form])

  // 设备选择变化时触发表单验证
  const handleDeviceChange = (devices: DeviceManagementTypes.DeviceListDto[]) => {
    setSelectedDevices(devices)
    form.validateFields(['deviceId']).catch(() => {
      // 忽略验证错误，只触发验证显示
    })
  }

  // 保存商户
  const handleSave = async () => {
    try {
      const values = await form.validateFields()
      setConfirmLoading(true)

      const identityType: number[] = []
      if (values.identityType?.includes('franchisee')) {
        identityType.push(1)
      }
      if (values.identityType?.includes('operator')) {
        identityType.push(2)
      }

      if (identityType.length === 0) {
        message.error('请至少选择一种商户身份')
        setConfirmLoading(false)
        return
      }

      const res = await addMerchantUser({
        merchantName: values.merchantName,
        contactUser: values.contactUser,
        contactPhone: values.contactPhone,
        idCard: values.idCard,
        businessLicense: values.businessLicense,
        remark: values.remark,
        identityType,
        deviceIdArr: selectedDevices.map(d => d.id)
      })

      if (res.code === ResultEnum.SUCCESS) {
        message.success('商户添加成功，账号密码短信已发送')
        onSuccess()
      } else {
        message.error(res.message || '添加失败')
      }
    } catch (e) {
      console.error(e)
    } finally {
      setConfirmLoading(false)
    }
  }

  return (
    <Modal
      title="新增商户"
      open={open}
      onCancel={onCancel}
      onOk={handleSave}
      confirmLoading={confirmLoading}
      width={720}
    >
      <Form form={form} layout="vertical" style={{ marginTop: 16 }}>
        <Form.Item
          label="商户名称"
          name="merchantName"
          rules={[{ required: true, message: '请输入企业名称或个人姓名' }]}
        >
          <Input placeholder="请输入商户名称" />
        </Form.Item>
        <Row gutter={16}>
          <Col span={12}>
            <Form.Item
              label="联系人姓名"
              name="contactUser"
              rules={[{ required: true, message: '请输入联系人姓名' }]}
            >
              <Input placeholder="请输入联系人姓名" />
            </Form.Item>
          </Col>
          <Col span={12}>
            <Form.Item
              label="联系人手机号"
              name="contactPhone"
              rules={[
                { required: true, message: '请输入手机号' },
                { pattern: /^1[3-9]\d{9}$/, message: '请输入正确的手机号' }
              ]}
            >
              <Input placeholder="作为登录账号和联系方式" />
            </Form.Item>
          </Col>
        </Row>
        <Form.Item
          label="商户身份"
          name="identityType"
          rules={[{ required: true, message: '请至少选择一种商户身份' }]}
        >
          <Checkbox.Group>
            <Checkbox value="franchisee">
              <Tag color="blue">商户</Tag>
            </Checkbox>
            <Checkbox value="operator">
              <Tag color="orange">运维人员</Tag>
            </Checkbox>
          </Checkbox.Group>
        </Form.Item>
        <p style={{ fontSize: 12, color: '#999', marginTop: -8, marginBottom: 16 }}>可同时勾选两种身份</p>
        <Row gutter={16}>
          <Col span={12}>
            <Form.Item
              label="身份证号"
              name="idCard"
              rules={[{
                validator: (_, value) => {
                  const businessLicense = form.getFieldValue('businessLicense')
                  if (!value && !businessLicense) {
                    return Promise.reject(new Error('身份证号和营业执照号至少填写一项'))
                  }
                  return Promise.resolve()
                }
              }]}
            >
              <Input placeholder="个人商户时填写" />
            </Form.Item>
          </Col>
          <Col span={12}>
            <Form.Item
              label="营业执照号"
              name="businessLicense"
              rules={[{
                validator: (_, value) => {
                  const idCard = form.getFieldValue('idCard')
                  if (!value && !idCard) {
                    return Promise.reject(new Error('身份证号和营业执照号至少填写一项'))
                  }
                  return Promise.resolve()
                }
              }]}
            >
              <Input placeholder="企业商户时填写" />
            </Form.Item>
          </Col>
        </Row>
        <Form.Item
          label="绑定设备"
          name="deviceId"
          required
          rules={[{
            validator: () => {
              if (selectedDevices.length === 0) {
                return Promise.reject(new Error('请至少选择一个设备'))
              }
              return Promise.resolve()
            }
          }]}
        >
          <DeviceSelector
            value={selectedDevices}
            onChange={handleDeviceChange}
            multiple={true}
          />
        </Form.Item>
        <Form.Item
          label="备注"
          name="remark"
        >
          <Input.TextArea rows={2} placeholder="请输入备注信息（选填）" />
        </Form.Item>
      </Form>
    </Modal>
  )
}

export default AddMerchantModal
